"""Authored practice questions for every lesson stage.

Each pool holds questions as Q(prompt, correct, [three wrong options], explanation, hint).
Pools are chosen by the planner's action type (see ACTION_POOLS in authored_content.py) and
every pool has at least two questions, so a learner asking for a similar question gets a new one.
The question each pool serves first on the practice step is applied: it asks the learner to read
code or work something out, so every stage's practice question exercises the skill, not just recall.
Prompts may embed a short code snippet between ``` fences; the learner UI renders it as code.
"""

from __future__ import annotations


Question = tuple[str, str, list[str], str, str]


def Q(prompt: str, correct: str, wrong: list[str], explanation: str, hint: str) -> Question:
    return (prompt, correct, [correct, *wrong], explanation, hint)


